nativeSource:
{
  --lini-font-family: Arial;
  .lini-block { font-family: Arial; }
  .lini-caption { translate: 0 -30; font-scale: 14 16; }
  .e1 { stroke: --teal-deep; }
  .e2 { stroke: --teal-deep; }
}
|group#visual| "V4 · Create before linking" { layout: flow; direction: column; gap: 72; padding: 36; fill: none; stroke: none; stroke-width: 0; } [
  |box#n1| "1 · create" { width: 240; } [
    |cell#detail| "Create the order at an explicit Key.\nSave the effect identity create; no\ncomputed or allocated identifier."
  ]
  |box#n2| "2 · link-customer" { width: 240; } [
    |cell#detail| "Source is created:create. Target is\nthe existing customer parameter, using\nthe authored relationship orientation."
  ]
  |box#n3| "3 · link-product" { width: 240; } [
    |cell#detail| "Source is created:create. Target is\nthe existing product parameter.\nForward references would refuse."
  ]
  |box#n4| "Permissions are separate" { width: 240; } [
    |cell#detail| "The frozen write frame must permit\ncreate and these relationships.\nEffects require the actual operations;\npermission alone does not."
  ]
  n1 -> n2 "2 · link-customer" .e1 { along: 0.35; }
  n1 -> n3 "3 · link-product" .e2 { along: 0.5; }
]
